-- Read-only (K-1213): does nutrition.food have every ingredient of the Turkish dishes? Generated by tools/gen_check_tr_ingredients.py
-- from data/food/tr-dishes.json; run it on the server:  psql -f tools/check_tr_ingredients.sql
-- wanted: the description, its FDC id when the file has one, 0 = the dish's own description and 1.. = an alternative, the dishes using it.
-- found: how many rows have that description (and which sources), and whether the FDC id's row is there. A dish is worked out when,
-- for each of its ingredients, the id or one of the descriptions is found: look for rows where rank = 0 and nothing is found, then
-- check that an alternative (rank above 0) is.
with wanted (description, fdc_id, rank, dishes) as (
    values
    ('Beans, snap, green, raw', null, 0, 1),
    ('Beans, white, mature seeds, cooked, boiled, without salt', null, 0, 1),
    ('Beef, ground, 85% lean meat / 15% fat, raw', null, 0, 12),
    ('Bread, white, commercially prepared (includes soft bread crumbs)', null, 0, 3),
    ('Bulgur, cooked', 170287, 0, 1),
    ('Bulgur, dry', 170688, 0, 4),
    ('Butter, salted', null, 0, 19),
    ('Cabbage, raw', null, 0, 1),
    ('Carrots, raw', null, 0, 1),
    ('Cheese, feta', null, 0, 8),
    ('Cheese, mozzarella, whole milk', null, 0, 2),
    ('Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw', 171077, 0, 2),
    ('Chicken, broilers or fryers, thigh, meat only, raw', null, 0, 1),
    ('Chickpeas (garbanzo beans, bengal gram), mature seeds, cooked, boiled, without salt', null, 0, 2),
    ('Cornstarch', null, 0, 2),
    ('Cucumber, with peel, raw', null, 0, 2),
    ('Egg, whole, raw, fresh', null, 0, 12),
    ('Eggplant, raw', null, 0, 4),
    ('Garlic, raw', null, 0, 5),
    ('Grape leaves, raw', 168575, 0, 1),
    ('Lamb, ground, raw', 174370, 0, 1),
    ('Lemon juice, raw', null, 0, 3),
    ('Lentils, mature seeds, cooked, boiled, without salt', null, 0, 1),
    ('Lentils, raw', 172420, 0, 2),
    ('Milk, whole, 3.25% milkfat, with added vitamin D', null, 0, 6),
    ('Nuts, walnuts, english', null, 0, 1),
    ('Oil, olive, salad or cooking', 171413, 0, 13),
    ('Oil, sunflower, linoleic (less than 60%)', null, 0, 19),
    ('Okra, raw', 169260, 0, 1),
    ('Onions, raw', null, 0, 24),
    ('Parsley, fresh', null, 0, 3),
    ('Pasta, dry, enriched', 169736, 0, 2),
    ('Peppers, sweet, green, raw', null, 0, 6),
    ('Peppers, sweet, red, raw', null, 0, 2),
    ('Potatoes, flesh and skin, raw', null, 0, 3),
    ('Rice, white, long-grain, regular, raw, enriched', null, 0, 9),
    ('Seeds, sesame butter, tahini, type of kernels unspecified', 168604, 0, 1),
    ('Seeds, sesame seeds, whole, dried', null, 0, 1),
    ('Semolina, enriched', 169715, 0, 2),
    ('Spinach, raw', null, 0, 2),
    ('Squash, summer, zucchini, includes skin, raw', null, 0, 1),
    ('Sugars, granulated', null, 0, 6),
    ('Tomato products, canned, paste, without salt added (Includes foods for USDA''s Food Distribution Program)', null, 0, 14),
    ('Tomatoes, red, ripe, raw, year round average', null, 0, 14),
    ('Wheat flour, white, all-purpose, enriched, bleached', null, 0, 16),
    ('Yogurt, plain, whole milk', 171284, 0, 12),
    ('Bread, white wheat', null, 1, 3),
    ('Bulgur, dry, raw', null, 1, 4),
    ('Chicken, broiler or fryers, thigh, meat only, raw', null, 1, 1),
    ('Chicken, broilers or fryers, breast, meat only, raw', null, 1, 2),
    ('Milk, whole, 3.25% milkfat, without added vitamin A and vitamin D', null, 1, 6),
    ('Oil, sunflower, linoleic, (approx. 65%)', null, 1, 19),
    ('Rice, white, long-grain, regular, raw, enriched, unspecified', null, 1, 9),
    ('Tomato products, canned, paste, without salt added', null, 1, 14),
    ('Wheat flour, white, all-purpose, enriched, unbleached', null, 1, 16),
    ('Oil, sunflower, linoleic (approx. 65%)', null, 2, 19)
)
select w.rank, w.description, w.fdc_id, w.dishes,
       (select string_agg(distinct f.source, ', ' order by f.source) from nutrition.food f
         where f.name = w.description and f.dataset = 'FDC' and f.source in ('FOUNDATION', 'SR_LEGACY', 'FNDDS')) as found_by_description,
       case when w.fdc_id is null then null
            else exists (select 1 from nutrition.food f where f.id = 'fdc:' || w.fdc_id) end as found_by_id
from wanted w
order by (select count(*) from nutrition.food f where f.name = w.description and f.dataset = 'FDC') = 0 desc, w.rank, w.description;
